"""Generated by OpenAI Codex on 2026-11-03. Opt-in, loopback-only OSM editing."""

import hashlib
import json
import math
import os
import secrets
import tempfile
from datetime import UTC, datetime
from pathlib import Path
from threading import Lock
from urllib.parse import urlsplit
from xml.etree import ElementTree as ET

from fastapi import APIRouter, HTTPException, Request
from fastapi.responses import JSONResponse

router = APIRouter(prefix="/api/map-editor", tags=["Local map editor"])
OSM_PATH = Path(__file__).resolve().parents[5] / "data/greater_cmu_area.osm"
TOKEN = secrets.token_urlsafe(32)
LOCK = Lock()
MAX_BYTES = 32 * 1024 * 1024


def guard(request: Request):
    if (
        os.environ.get("CATS_MAP_EDITOR") != "1"
        or os.environ.get("AUTH_REQUIRED", "0") != "0"
    ):
        raise HTTPException(404, "Local editor is disabled")
    host = request.url.hostname
    if (
        host not in {"localhost", "127.0.0.1", "::1"}
        or not request.client
        or request.client.host not in {"127.0.0.1", "::1"}
    ):
        raise HTTPException(403, "Map editing requires a loopback connection")
    origin = request.headers.get("origin")
    allowed = {
        "http://localhost:8081",
        "http://localhost:8082",
        "http://127.0.0.1:8082",
        "http://127.0.0.1:8081",
        "http://localhost:8000",
        "http://127.0.0.1:8000",
    }
    if origin not in allowed:
        raise HTTPException(403, "Open the editor on localhost:8081")
    if urlsplit(origin).scheme != "http":
        raise HTTPException(403, "Invalid editor origin")


def revision(content: bytes):
    return hashlib.sha256(content).hexdigest()


def parse(content: bytes):
    if (
        len(content) > MAX_BYTES
        or b"<!DOCTYPE" in content.upper()
        or b"<!ENTITY" in content.upper()
    ):
        raise ValueError("File is too large or contains forbidden XML declarations")
    root = ET.fromstring(content)
    if root.tag != "osm" or root.get("version") != "0.6":
        raise ValueError("Expected an OSM 0.6 document")
    objects = {}
    refs = set()
    for obj in root:
        if obj.tag in {"bounds", "note", "meta"}:
            continue
        if obj.tag not in {"node", "way", "relation"}:
            raise ValueError("Unsupported OSM object")
        key = (obj.tag, obj.attrib["id"])
        int(key[1])
        if key in objects:
            raise ValueError("Duplicate OSM ID")
        objects[key] = obj
        tags = [tag.attrib["k"] for tag in obj.findall("tag")]
        if len(tags) != len(set(tags)) or any(not tag.strip() for tag in tags):
            raise ValueError("Tag keys must be nonempty and unique")
        for tag in obj.findall("tag"):
            if "v" not in tag.attrib:
                raise ValueError("Every tag needs a value")
        if obj.tag == "node":
            lat, lon = float(obj.attrib["lat"]), float(obj.attrib["lon"])
            if not (
                math.isfinite(lat)
                and math.isfinite(lon)
                and -90 <= lat <= 90
                and -180 <= lon <= 180
            ):
                raise ValueError("Invalid coordinates")
        elif obj.tag == "way":
            nodes = [nd.attrib["ref"] for nd in obj.findall("nd")]
            if len(nodes) < 2 or (nodes[0] == nodes[-1] and len(set(nodes)) < 3):
                raise ValueError(
                    "Ways need two nodes; closed boundaries need three distinct vertices"
                )
            refs.update((key, ("node", node)) for node in nodes)
        else:
            for member in obj.findall("member"):
                kind, ref = member.attrib["type"], member.attrib["ref"]
                if kind not in {"node", "way", "relation"}:
                    raise ValueError("Invalid relation member")
                refs.add((key, (kind, ref)))
    return objects, refs


def save(content: bytes, expected: str):
    # Serialize reads/checks/backups/replacement within this local single-worker service.
    with LOCK:
        previous = OSM_PATH.read_bytes()
        if revision(previous) != expected:
            raise HTTPException(
                409,
                "The OSM file changed on disk. Export your draft, then reload before saving.",
            )
        try:
            objects, refs = parse(content)
            old_objects, old_refs = parse(previous)
            old_missing = {edge for edge in old_refs if edge[1] not in old_objects}
            missing = {edge for edge in refs if edge[1] not in objects}
            if missing - old_missing:
                raise ValueError(
                    "An edited object references a missing node, way, or relation"
                )
            if not objects:
                raise ValueError("Refusing to save an empty dataset")
        except (ValueError, KeyError, ET.ParseError) as exc:
            raise HTTPException(422, str(exc)) from exc
        backups = OSM_PATH.parent / ".osm-backups"
        backups.mkdir(exist_ok=True)
        name = datetime.now(UTC).strftime("%Y%m%dT%H%M%S%fZ") + ".osm"
        (backups / name).write_bytes(previous)
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(
                dir=OSM_PATH.parent, delete=False
            ) as handle:
                temporary = Path(handle.name)
                handle.write(content)
                handle.flush()
                os.fsync(handle.fileno())
            temporary.chmod(OSM_PATH.stat().st_mode & 0o777)
            os.replace(temporary, OSM_PATH)
        finally:
            if temporary and temporary.exists():
                temporary.unlink()
        return {"revision": revision(content), "backup": name}


@router.get("")
def load(request: Request):
    guard(request)
    content = OSM_PATH.read_bytes()
    return JSONResponse(
        {"xml": content.decode("utf-8"), "revision": revision(content), "token": TOKEN},
        headers={"Cache-Control": "no-store"},
    )


@router.post("")
async def write(request: Request):
    guard(request)
    if not secrets.compare_digest(request.headers.get("x-map-editor-token", ""), TOKEN):
        raise HTTPException(403, "Editor token missing or expired; reload the editor")
    body = bytearray()
    async for chunk in request.stream():
        body.extend(chunk)
        if len(body) > MAX_BYTES * 2:
            raise HTTPException(413, "Editor request too large")
    try:
        payload = json.loads(body)
        content = payload["xml"].encode("utf-8")
        expected = payload["revision"]
        if not isinstance(expected, str):
            raise TypeError("Invalid revision")
    except (ValueError, KeyError, TypeError, AttributeError) as exc:
        raise HTTPException(422, "Expected XML and revision") from exc
    return save(content, expected)
